style.css:
@-moz-document domain("google.com"), domain("google.com.br") {
/* 1. Fundo principal e cor do texto geral */
    body, #gsr, .g, .MainPage {
        background-color: #0f1115 !important;
        color: #e3e6eb !important;
    }

    /* 2. Barra de pesquisa do Google */
    .RNNXgb, .SDkEP, .gLFyf {
        background-color: #1a1d24 !important;
        border: 1px solid #2d323f !important;
        border-radius: 24px !important;
        color: #ffffff !important;
    }
    
    /* Efeito de brilho ao passar o mouse na barra de pesquisa */
    .RNNXgb:hover, .RNNXgb:focus-within {
        background-color: #1e222b !important;
        box-shadow: 0 1px 6px rgba(0, 180, 216, 0.4) !important;
        border-color: #00b4d8 !important;
    }

    /* 3. Títulos dos resultados de pesquisa */
    h3, .LC20lb, .DKV0Md {
        color: #00b4d8 !important; /* Azul neon moderno */
    }
    h3:hover, .LC20lb:hover {
        text-decoration: underline !important;
    }

    /* 4. Links visitados (para não ficarem roxos feios) */
    a:visited h3, a:visited .LC20lb {
        color: #90e0ef !important;
    }

    /* 5. Pequenos textos de descrição dos resultados (Snippets) */
    .VwiC3b, .MUxGbd, .st {
        color: #a5aebc !important;
    }

    /* 6. URLs verdes/cinzas abaixo dos títulos */
    .tjv60b, .byrY5, .VuuXrf {
        color: #00f5d4 !important; /* Um tom verde-água para as URLs */
    }

    /* 7. Botões "Pesquisa Google" e "Estou com sorte" */
    .FPdoLc input[type="submit"], .gNO89b, .RNmpXc {
        background-color: #1a1d24 !important;
        color: #e3e6eb !important;
        border: 1px solid #2d323f !important;
        border-radius: 6px !important;
    }
    .FPdoLc input[type="submit"]:hover, .gNO89b:hover {
        background-color: #252a34 !important;
        border-color: #00b4d8 !important;
        color: #fff !important;
    }

    /* 8. Caixa de "As pessoas também perguntam" e painéis laterais */
    .Ww4FFb, .g, .jtfY8c, .li046c {
        background-color: #14171e !important;
        border: 1px solid #2d323f !important;
        border-radius: 12px !important;
    }

    /* 9. Corrigir o logo clássico do Google para não contrastar demais (opcional - deixa ele levemente translúcido) */
    .lnXffd, .k1zDkc, .logo img {
        filter: drop-shadow(0px 0px 2px rgba(255,255,255,0.2)) !important;
    }
}
